"""Curated source questions; citations are checked against the supplied PDF text."""
import json,re,hashlib
from pathlib import Path

root=Path(__file__).parent
lectures={d['id']:d for d in json.loads((root/'lectures/lectures.json').read_text(encoding='utf8'))}
source_pages={i:json.loads((root/f'tmp/papers/paper{i}-pages.json').read_text(encoding='utf8')) for i in (1,2,3)}
norm=lambda s:re.sub(r'\s+',' ',s).strip()
def ev(slug,page,needle=''):
    text=norm(lectures[slug]['pages'][page-1]['text'])
    if needle:
        start=text.lower().find(needle.lower())
        if start<0:raise ValueError(f'Evidence not found: {slug} p{page}: {needle}')
        excerpt=text[max(0,start-45):start+len(needle)+190]
    else:excerpt=text[:420]
    return {'lectureId':slug,'page':page,'excerpt':excerpt}
def refs(slug,*pages):return [ev(slug,p) for p in pages]
bank=json.loads((root/'papers/checked-question-bank.json').read_text(encoding='utf8'))['questions'][:5]
for q in bank:
    q['verification']='moodle-key'
    q['sourceRefs']=[]
    q['evidence']=[]
base_sources=[(2,1),(2,3),(3,1),(3,3),('image',2)]
for q,(paper,page) in zip(bank,base_sources):q['sourceRefs']=[{'paper':paper,'page':page}]
bank[2].update(verification='lecture-supported',evidence=refs('acid-base',61,65,71,72))
bank[2]['explanation']='Vomiting gastric contents removes H+ and chloride and can produce hypochloremic metabolic alkalosis. Diarrhea and impaired renal bicarbonate reabsorption instead produce normal-anion-gap metabolic acidosis. These mechanisms agree with the Moodle feedback.'
bank[3].update(verification='lecture-supported',evidence=refs('nutrition',21,24)+refs('nutrition-2025',42))
bank[3]['explanation']='Stress starvation during serious illness causes intensive protein catabolism, hyperglycemia, and insulin resistance with hyperinsulinemia. This differs from simple starvation. The lecture supports the two options listed in Moodle feedback.'
bank[4].update(evidence=refs('edema',9,14))
bank[4]['explanation']+=' The exact three-category answer is an exam-key convention; the lecture also describes additional classification schemes. It is not a claim that no other edema classification exists.'
written=[]
def add(slug,topic,question,options,correct,pages,explanation,evidence,basis='lecture-supported',paper=3):
    q={'id':'verified-'+slug,'topic':topic,'paper':f'Paper {paper} · PDF page '+', '.join(map(str,pages)), 'question':question,'options':options,'correct':correct,'explanation':explanation,'verification':basis,'sourceRefs':[{'paper':paper,'page':p} for p in pages],'evidence':evidence}
    bank.append(q)
    return q
def writtenq(slug,topic,question,paper,pages,rubric,evidence):
    written.append({'id':'written-'+slug,'topic':topic,'question':question,'sourceRefs':[{'paper':paper,'page':p} for p in pages],'rubric':rubric,'evidence':evidence})

add('b12-absorption','Vitamins','The intrinsic factor complex with cobalamin (vitamin B12) is absorbed', ['By paracellular transport in the jejunum and ileum','By facilitated diffusion in the ileum','Using receptors in the area of the brush border of the ileum','In the cells of the gastric pylorus'],[2],[2,126],'The lecture describes binding of the intrinsic-factor–B12 complex to specific cubilin receptors in the distal ileum, followed by endocytosis. This is receptor-mediated uptake, not paracellular transport or facilitated diffusion.',refs('nutrition-2025',20))
add('simple-starvation','Nutrition and starvation','Choose the correct statement about simple starvation', ['During the first 10–12 hours, the body receives energy mainly due to lipolysis','On day 14, the patient will likely have metabolic alkalosis due to proteolysis','Approximately 4–5 kilograms of body muscle will be lost during the first 7 days of fasting','After a few days, energy metabolism decreases','Adult patients can usually survive for more than 4 weeks if they consume only water'],[3,4],[5,7,123],'Moodle feedback lists reduced energy metabolism and survival beyond four weeks with water. The lecture corroborates early glycogen use, later ketogenesis and reduced metabolism, but does not establish the exact survival duration or muscle-loss number. The complete answer set therefore retains its Moodle-key status.',refs('nutrition',20,21)+refs('nutrition-2025',39),basis='moodle-key')
add('hypercholesterolemia','Lipid metabolism','Select conditions associated with hypercholesterolemia', ['Type II diabetes mellitus','Hypothyroidism','Anorexia nervosa','Nephrotic syndrome','Hepatocellular carcinoma with cachexia'],[0,1,2,3],[5],'The four-option answer set is stated in Moodle feedback. The supplied lectures explicitly corroborate diabetes, hypothyroidism and nephrotic syndrome as secondary dyslipidemias. Anorexia nervosa is retained from the source key; that association is not explicitly established in these lecture passages.',refs('vitamins-lipids-gout',32)+refs('nutrition-2025',87),basis='moodle-key')
add('vitamin-deficiencies','Vitamins','Select the typical symptoms of vitamin deficiency', ['Vitamin A deficiency leads to night blindness, xerophthalmia, and keratinization of skin and mucous membranes','Vitamin D deficiency increases the risk of mood swings and depression','Vitamin C deficiency significantly increases the risk of thrombosis','Vitamin D deficiency increases the risk of muscle weakness and muscle spasms','Long-term use of broad-spectrum antibiotics can lead to vitamin K deficiency and increased bleeding'],[0,1,3,4],[9,112,120],'The answer set is reproduced from readable Moodle feedback. Lecture passages support the vitamin A and K associations, vitamin D deficiency, and vitamin C deficiency causing impaired collagen formation and bleeding. The mood/depression association is retained from Moodle feedback rather than claimed to be established by the supplied vitamin D slides.',refs('vitamins-lipids-gout',18,19,24,25),basis='moodle-key')
add('intermittent-fasting','Nutrition and starvation','Intermittent fasting can mean that a person:', ['Consumes only one type of food each week','Consumes a low-protein diet for one day, a low-fat diet for one day, then a low-carbohydrate diet for one day','Consumes food for 6 hours a day and does not consume food for 18 hours','Consumes food for 8 hours a day and does not consume food for 16 hours','Consumes only one type of food each day'],[2,3],[11,63,145],'The Moodle feedback identifies the 6/18 and 8/16 eating/fasting windows. Changing the type of food each day or week is not the defining time restriction. The supplied lectures do not explicitly verify these exact windows.',[],basis='moodle-key')
add('hypochloremia','Acid–base balance','Hypochloremia is seen in', ['Edematous conditions associated with dilutional hyponatremia','Excessive losses of HCO3− from the organism through the GIT or kidneys','Isotonic dehydration','Hypertonic dehydration','Metabolic alkalosis during vomiting'],[0,4],[16,136],'Moodle feedback lists dilutional edematous states and vomiting-associated metabolic alkalosis. Vomiting removes chloride. Bicarbonate loss instead causes relative chloride retention and hyperchloremic metabolic acidosis. The exact dilutional-state answer is taken from the source key.',refs('acid-base',38,61,72),basis='moodle-key')
add('iron','Anemia','Choose the correct statement(s) about iron', ['Microcytic anemia, dysphagia and atrophic gastritis can be manifestations of iron deficiency','Iron deficiency often occurs in patients with chronic blood loss','Iron can accumulate in cells of the pancreas, liver and heart after multiple transfusions','Iron overload never happens','Iron is absorbed mostly in the terminal ileum'],[0,1,2],[18],'The complete answer set is visible in Moodle feedback. The supplied vitamin lecture corroborates repeated transfusions causing iron overload and deposition in organs; it does not cover every iron-deficiency statement here. This remains a Moodle-key question rather than a fully lecture-verified item.',refs('vitamins-lipids-gout',7),basis='moodle-key')
add('vitamin-b12','Vitamins','Choose the correct statement(s) about vitamin B12', ['The recommended daily intake of B12 is 70–150 mg for adults','Vitamin B12 deficiency leads to hyperhomocysteinemia with increased risk of endothelial damage','B12 is mostly reabsorbed in the duodenum','Vitamin B12 deficiency can lead to macrocytic anemia and nerve demyelination','Gastric resection leads to B12 absorption disorders'],[1,3,4],[21],'The lecture describes ileal receptor-mediated absorption, impaired absorption after gastric resection, impaired DNA synthesis causing megaloblastic anemia, and neurological consequences involving myelin. Its homocysteine pathway supports the vascular association. The full three-option set also matches Moodle feedback; the large intake number is not supported by the lecture.',refs('nutrition-2025',20,21)+refs('vitamins-lipids-gout',14,15),basis='moodle-key')
add('edema-not-classification','Edema and body fluids','The following characteristics are NOT used to classify edema (according to the displayed exam key):', ['Pitting and non-pitting','Acquired and inherited','Hyperosmolar and hypoosmolar','Local and generalized','Primary and secondary lymphedema'],[1,2],[24,55],'Moodle feedback gives acquired/inherited and hyperosmolar/hypoosmolar. This is a restricted exam convention. The lecture describes several classification schemes, and inherited/acquired distinctions can be meaningful for lymphatic disease; do not treat the exam wording as a universal prohibition.',refs('edema',9,13,14),basis='moodle-key')
add('peptic-ulcer','Digestive system','Choose the correct statement(s) about ulcer disease', ['Increased amounts of pepsinogen or proteinases are present in many patients with gastric ulcers','Nonsteroidal anti-inflammatory drugs are significant risk factors for ulcer formation','The influence of the autonomic nervous system on ulcer development is negligible','Helicobacter pylori is important in duodenal ulcers but plays no role in gastric ulcers','Increased HCl production is a significant factor in duodenal ulcer development'],[0,1,4],[25,27],'The gastric-ulcer lecture describes a cycle of mucosal injury, histamine release, and increased pepsinogen production. NSAIDs impair prostaglandin-dependent protection. Vagal stimulation affects acid and pepsin secretion, H. pylori contributes to gastric as well as duodenal ulcers, and duodenal ulceration is associated with hyperacidity.',refs('digestive',35,41,42,43))
add('malabsorption','Malassimilation','Malabsorption syndrome', ['Is usually accompanied by a tendency to metabolic alkalosis as a result of diarrhea','Is usually accompanied by diarrhea','Is most often related to stomach disorders','May present with hypochromic or megaloblastic anemia','Is usually accompanied by obstinate constipation'],[1,3],[29,114],'The lectures describe diarrhea and malabsorption of iron, folate and B12, explaining the anemia patterns. They locate major causes in intestinal, pancreatic and bile-salt disease. Bicarbonate loss in diarrhea favors metabolic acidosis, not alkalosis.',refs('nutrition',28,30,34,35)+refs('acid-base',61,62))
add('siadh','Edema and body fluids','Choose the correct statement(s) about SIADH', ['Swelling of the lower extremities is common','One cause of SIADH is pneumonia','Incorrect treatment can lead to pontine demyelination','It may cause hyponatremia','It is associated with a reduced level of ANP'],[1,2,3],[36,53,54,57,102,146],'Excess ADH retains water and causes dilutional hyponatremia. Pulmonary disorders can precipitate SIADH. Compensatory ANP helps explain why peripheral edema is usually absent. Rapid correction of chronic hyponatremia can cause osmotic demyelination. These mechanisms agree with the Moodle feedback.',refs('hydration',40,41)+refs('edema',23,24))
add('diarrhea','Acid–base balance','Major diarrhea will lead to', ['Metabolic acidosis due to compensatory HCl formation','Metabolic alkalosis due to bicarbonate loss','Metabolic alkalosis due to compensatory hyperkalemia','Metabolic acidosis due to bicarbonate loss','Dehydration'],[3,4],[46,48],'Loss of bicarbonate-rich intestinal fluid causes metabolic acidosis, usually with a normal anion gap and relative hyperchloremia. Fluid loss can cause dehydration. The mechanism is loss of base rather than compensatory hydrochloric acid production.',refs('acid-base',61,62)+refs('hydration',49))
add('contraction-alkalosis','Acid–base balance','Acute depletion of extracellular fluid by diuretic therapy (excluding carbonic-anhydrase inhibitors), with loss of water and NaCl', ['Does not affect acid–base balance','Can cause acidosis from dehydration','Leads to renal bicarbonate losses','May cause alkalosis from dehydration'],[3],[50,51],'Loop and thiazide diuretics can cause volume-contraction alkalosis with salt and potassium losses. Carbonic-anhydrase inhibitors are explicitly excluded because they cause renal bicarbonate loss and metabolic acidosis.',refs('acid-base',28,71,79))
add('hirschsprung','Digestive system',"Hirschsprung’s disease (megacolon congenitum)", ['Is congenital and involves missing ganglion cells in the intestinal plexus','Manifests as diarrhea caused by insufficient fat digestion','Manifests as organic constipation with stagnation of intestinal contents','Is an intestinal manifestation of congenital progressive myodystrophy'],[0,2],[52,76],'The digestive lecture identifies congenital aganglionic megacolon: ganglion cells of the myenteric plexus are absent. Loss of coordinated propulsion causes obstruction and constipation, rather than a primary fat-digestion disorder.',refs('digestive',65)+refs('digestive',50))
add('starvation-acidosis','Acid–base balance','Which acid–base disorder develops primarily during long-term simple starvation?', ['Combined metabolic and respiratory acidosis','Metabolic acidosis','Respiratory acidosis','Metabolic alkalosis','Respiratory alkalosis'],[1],[56,87],'Starvation increases ketone-body production. Accumulation of ketoacids produces a primary metabolic acidosis; respiratory compensation is not a second primary respiratory acidosis.',refs('acid-base',13,51,57)+refs('nutrition',20))
add('gout','Purine metabolism and gout','Select processes common in the pathogenesis of gout', ['Myocardial infarction is often the initial sign of gout','Hyperemia and severe pain in the affected joint during exacerbation','High blood urea','Uric acid crystals precipitate in the joint cavity','Tophi appear on the hands, fingers, elbows and ears with progression'],[1,3,4],[59,89,90,136],'Gout involves urate crystals and crystal-triggered inflammatory injury, causing painful inflammatory attacks and chronic tophaceous deposits. Urea is not uric acid. The anatomical tophus list and full answer set are stated in Moodle feedback, with the urate mechanism corroborated by lectures.',refs('vitamins-lipids-gout',27,28),basis='moodle-key')
add('dka-case','Diabetic ketoacidosis','A 12-year-old boy has decompensated type 1 diabetes after insufficient insulin. Glucose is 20.9 mmol/L, blood pH 7.1, and he is severely dehydrated. Select correct statements.', ['Tachycardia is likely because of dehydration and sympathetic activation','The anion gap is likely normal or reduced','Blood osmolarity is likely high','Dehydration is likely due to osmotic diuresis','Plasma ketone bodies are likely increased'],[0,2,3,4],[60],'Insulin deficiency increases lipolysis and hepatic ketogenesis, producing high-anion-gap metabolic acidosis. Hyperglycemia causes osmotic diuresis and dehydration. Hypovolemia causes sympathetic tachycardia. This matches the Moodle feedback.',refs('dka',2,3,4,5)+refs('hydration',9,46))
add('hyperchloremic-acidosis','Acid–base balance','Choose the correct statement(s) about hyperchloremic acidosis', ['May be caused by vomiting','The anion gap is usually normal','May be caused by diarrhea','Is a type of respiratory acidosis','May be caused by a panic attack'],[1,2],[62],'In this source question, vomiting refers to ordinary gastric-content loss, which favors alkalosis. Intestinal bicarbonate loss from diarrhea instead produces normal-anion-gap hyperchloremic metabolic acidosis. A panic attack may cause respiratory alkalosis. The two-option answer set matches Moodle feedback.',refs('acid-base',54,61,62,71),basis='moodle-key')
add('hiatal-hernia','Digestive system','Hiatal hernia', ['Often leads to liver cirrhosis','Can manifest as heartburn','Can lead to hernia strangulation or obstruction','Often manifests as diarrhea','Is an important cause of celiac disease'],[1,2],[68],'Sliding hiatal hernia promotes reflux and heartburn; paraesophageal hernia may become mechanically strangulated. The different complications refer to different hernia types. Celiac disease is a gluten-related immune disorder.',refs('digestive',24,25,26)+refs('nutrition',30))
add('lactose-hydrolysis','Malassimilation','Lactose intolerance in adults is caused by', ['Excessive splitting of lactose into glucose and galactose in the intestine','Impaired lactose hydrolysis in the intestine','A malfunction of mechanisms transporting lactose and galactose through the intestinal wall','A disorder of lactose phosphorylation in the intestinal wall'],[1],[69,75],'Lactase deficiency leaves lactose undigested. It is then fermented by bacteria and retains water osmotically, causing gas, pain and diarrhea. The primary defect is hydrolysis of lactose, not phosphorylation or an increased rate of splitting.',refs('nutrition',29))
add('insulin-potassium','Sodium and potassium','Administering insulin infused with glucose has which effect on potassium?', ['None','Potassium tends to rise because insulin reduces urinary potassium excretion','Potassium falls because insulin causes potassium to enter cells','Potassium rises because insulin causes potassium to leave cells'],[2],[80,81],'The sodium/potassium lecture lists high insulin as a cause of an extracellular-to-intracellular potassium shift and hypokalemia. The question concerns plasma potassium, not an increase or decrease in total-body potassium.',refs('sodium-potassium',10)+refs('dka',5))
add('metabolic-alkalosis-causes','Acid–base balance','Causes of metabolic alkalosis include', ['The effect of carbonic-anhydrase inhibitors','Hyperkalemia','Primary hyperaldosteronism','Vomiting'],[2,3],[83],'Aldosterone increases renal H+ and K+ excretion; gastric vomiting removes acid and chloride. Carbonic-anhydrase inhibitors instead cause bicarbonate loss and hyperchloremic metabolic acidosis.',refs('acid-base',28,71,72,75))
add('secondary-hyperaldosteronism','Sodium and potassium','Secondary hyperaldosteronism', ['Reduces the urinary Na/K concentration ratio','Leads to metabolic acidosis','Increases the urinary Na/K concentration ratio','Leads to metabolic alkalosis','Can increase arterial blood pressure'],[0,3,4],[85,86],'Aldosterone favors sodium reabsorption and potassium/H+ excretion, reducing the urinary Na/K ratio and favoring alkalosis. RAAS activity can increase blood pressure. Hypertension and hypokalemia may be less prominent than in primary hyperaldosteronism; the option says “can,” not “always.”',refs('hydration',23,27,30)+refs('acid-base',75))
add('lactase-deficiency','Malassimilation','Lactase deficiency', ['Causes intolerance to milk and some dairy products',"Causes Crohn’s disease",'Some patients develop diarrhea and pain after dairy products while others have minimal problems','Causes animal-fat intolerance','Causes intolerance to gluten-containing foods'],[0,2],[93,95],'Lactase deficiency causes poor digestion of lactose and variable symptoms related to the lactose load, including osmotic diarrhea, gas and cramps. It does not define fat intolerance or the gluten-driven process of celiac disease.',refs('nutrition',29,30))
add('buffer-response-order','Acid–base balance','In a metabolic acid–base disturbance, which sequence describes the responses leading toward restoration?', ['Compensation, buffer reaction, correction','Buffer reaction, correction, compensation','Buffer reaction, compensation, correction','Correction, compensation, buffer reaction'],[2],[98],'Chemical buffers react immediately, the respiratory system responds within minutes, and renal responses develop more slowly. For a primary metabolic disorder these correspond to buffering, respiratory compensation, and renal correction when renal function permits.',refs('acid-base',51,52))
add('celiac-infant','Malassimilation','An 8-month-old boy develops intermittent diarrhea, poor appetite, abdominal pain and bloating after weaning and introduction of baked goods. He loses approximately 0.5 kg in two weeks, without vomiting or fever. What is the most likely diagnosis among these options?', ['Lactose intolerance','Phenylketonuria','Cystic fibrosis','Celiac disease','Fructose intolerance'],[3],[100],'The timing after introduction of gluten-containing food and the malabsorptive symptoms favor celiac disease among the listed answers. The lecture describes gluten-related immune injury, diarrhea/steatorrhea, abdominal pain and failure to gain weight. This is an exam vignette, not a diagnosis from symptoms alone.',refs('nutrition',30,31))
add('crohn-location','Digestive system',"Which statement applies to Crohn’s disease?", ['The sigmoid and rectum are most often affected','The terminal ileum and adjacent cecum are most often affected','H. pylori is the most important etiological factor','Inflammation spreads continuously','The mucosa is affected diffusely'],[1],[105],'The lecture describes common involvement of distal small bowel and proximal large bowel with patchy skip lesions and transmural inflammation. Continuous diffuse colonic mucosal inflammation extending from the rectum describes ulcerative colitis instead.',refs('nutrition',36,37,38,40))
add('potassium-physiology','Sodium and potassium','Which statements apply to plasma potassium?', ['It decreases with tissue breakdown, burns and hemolysis','In metabolic alkalosis potassium is released from binding to intracellular phosphates and proteins','Its distribution depends on adequate energy for Na+/K+-ATPase function','It is influenced by the current state of renal function'],[2,3],[33,113],'Tissue breakdown releases intracellular potassium and may raise plasma potassium. Alkalemia favors cellular uptake rather than the stated release. ATP-dependent pumping and renal excretion both influence plasma potassium.',refs('sodium-potassium',2,3,4,10))
add('duodenal-ulcer','Digestive system','Duodenal ulcer is multifactorial. Which factors have a significant role in its development?', ['Increased gastrin output','Reduced vagal tone','Smoking','Duodenal epithelial dysplasia caused by hypersecretion of digestive enzymes','Chronic Helicobacter pylori infection'],[0,2,4],[117],'Gastrin increases acid secretion, nicotine is listed as an aggressive factor, and H. pylori is strongly associated with duodenal ulceration. Vagal stimulation increases acid/pepsin secretion, so reduced vagal tone is not the stated ulcer-promoting mechanism. The dysplasia/enzyme option does not describe the lecture mechanism.',refs('digestive',33,35,42,43))
add('hypoproteinemia','Edema and body fluids','Decreased plasma protein levels', ['Activate the renin–angiotensin–aldosterone system','Decrease potassium excretion','Increase water movement from blood into the interstitium','Help treat ascites','Increase sodium excretion'],[0,2],[118],'Lower plasma oncotic pressure favors fluid movement into the interstitium. Reduced effective circulating volume can secondarily activate RAAS, favoring sodium retention and potentially increased potassium excretion. The item is interpreted in the edema/underfilling context described by the lecture.',refs('edema',7,13,14)+refs('hydration',21,23))
add('vomiting','Acid–base balance','Major vomiting will lead to', ['Metabolic acidosis due to large chloride losses','Metabolic alkalosis due to large hydrogen-ion losses in acidic gastric juice','Hypochloremia','Metabolic acidosis due to compensatory HCl formation','Metabolic alkalosis due to compensatory hyperkalemia'],[1,2],[124],'Loss of gastric HCl produces chloride depletion and metabolic alkalosis. Potassium depletion may maintain alkalosis; compensatory hyperkalemia is not the explanation. The two-option answer set matches Moodle feedback.',refs('acid-base',71,72,73))
add('sweating-dehydration','Edema and body fluids','Which changes are typical of severe dehydration caused by sweating without replacement by drinking?', ['Tachycardia due to parasympathetic activation','Decreased plasma sodium concentration due to sodium loss in sweat','No answer is correct','Increased total-body sodium due to increased ANP secretion','Increased arterial blood pressure due to sympathetic activation'],[2],[125,143],'The source key selects “No answer is correct.” Sweat loss commonly removes relatively more water than salt, favoring hypertonic dehydration. Hypovolemia produces sympathetic tachycardia and tends toward hypotension, not parasympathetic tachycardia or a typical blood-pressure increase. ANP favors natriuresis rather than sodium accumulation.',refs('hydration',17,22,46,49))
add('celiac-typical','Malassimilation','What is typical of celiac disease?', ['A gluten-induced autoimmune response','A lactose-induced autoimmune response','Frequent association with other autoimmune diseases','A lifelong strict gluten-free diet is the best treatment','A reduced number of lymphocytes in the intestinal mucosa'],[0,2,3],[133],'The lecture supports gluten-associated immune injury and anti-transglutaminase antibodies. The autoimmune association and lifelong dietary treatment are standard celiac features, but these exact two claims require additional clinical-source support. This item is held out of grading pending that support.',refs('nutrition',30,31),basis='pending')
add('hyperkalemia','Sodium and potassium','Choose the correct statement(s) about hyperkalemia', ['May cause arrhythmias','Is a side effect of insulin therapy','Is associated with hyperaldosteronism','May cause paresthesia and muscle weakness','Is typical of end-stage renal insufficiency'],[0,3,4],[139],'The lecture lists renal failure as a cause and neuromuscular weakness/paresthesia and arrhythmias as manifestations. Insulin shifts potassium into cells; excess aldosterone increases potassium excretion and typically favors hypokalemia.',refs('sodium-potassium',3,4,5,7,10))

# Japanese-drive printed variants: separate from the remembered, modified exam variants.
add('jp-duodenal','Digestive system','Pathogenetic factors of duodenal ulcer development include', ['Chronic Helicobacter pylori infection','Increased gastrin output','Decreased vagal tone','Duodenal epithelial dysplasia caused by hypersecretion of digestive enzymes'],[0,1],[1],'This reproduces the complete printed question, whose filled markers identify a and b. The lecture supports H. pylori and gastrin/acid mechanisms. The Japanese note refers to a modified version with an additional unidentified statement; that missing version is not reconstructed.',refs('digestive',33,35,42,43),paper='image')
add('jp-diarrhea','Acid–base balance','Profuse diarrhea leads to', ['Metabolic acidosis','A tendency toward hypokalemia','A tendency toward hyperchloremia','Metabolic alkalosis'],[0,1,2],[1],'The lecture explicitly describes intestinal bicarbonate loss causing normal-anion-gap hyperchloremic metabolic acidosis, with hypokalemia possible because stool contains potassium. This agrees with the printed filled markers. The note about different options in another exam is retained separately.',refs('acid-base',61,62),paper='image')
add('jp-hypertonic-dehydration','Edema and body fluids','Hypertonic dehydration is a sign of', ['The polyuric phase of acute renal failure','Vomiting','Diabetes insipidus','Use of hypertonic solutions for infusion therapy'],[0,2],[1],'The lecture explicitly lists the polyuric phase of acute renal failure and low ADH/diabetes insipidus under hypertonic dehydration, agreeing with the printed a/c markers. The broad “vomiting” option is ambiguous because it does not specify losses and replacement; this printed key remains exam-key practice, not a universal claim that vomiting cannot produce hypertonic dehydration. Hypertonic infusion adds solute and does not itself define dehydration.',refs('hydration',49,52),basis='printed-key',paper='image')

writtenq('hydrostatic-edema','Edema and body fluids','Describe the pathogenesis of edema caused by increased hydrostatic pressure and give three examples.',2,[9],['Raised capillary hydrostatic pressure increases outward fluid filtration into the interstitium beyond lymphatic removal.','Examples include right-sided congestive heart failure, venous insufficiency, and deep venous thrombosis. Tumor compression of a vein is another acceptable example.','Distinguish the hydrostatic mechanism from low plasma oncotic pressure and inflammatory permeability.'],refs('edema',4,5,6))
writtenq('crohn-pathogenesis','Digestive system',"Explain the pathogenesis of Crohn’s disease.",2,[11],['An inappropriate immune response to intestinal flora in a genetically predisposed person; the lecture describes a Th1-associated response.','Patchy skip lesions, commonly involving terminal ileum/proximal colon, with granulomatous transmural inflammation.','Chronic injury may cause ulceration, fibrosis/stenosis, obstruction, abscesses and fistulas. The disease is not confined to mucosa.'],refs('nutrition',36,37,38))
writtenq('dehydration-types','Edema and body fluids','Define dehydration and give six examples divided into its three subtypes.',2,[12],['Dehydration is a deficit of body water/fluid; tonicity depends on the relative water and sodium loss.','Isotonic: hemorrhage; third-space loss in pancreatitis or ileus.','Hypotonic: salt loss from low aldosterone; excessive loop-diuretic loss.','Hypertonic: diabetes insipidus; profuse sweating without adequate water replacement.','Explain direction of cellular water movement: hypotonic extracellular fluid favors cellular swelling; hypertonic fluid causes cellular water loss.'],refs('hydration',46,49))
writtenq('dysphagia','Digestive system','Define dysphagia and give six important causes.',2,[15],['Dysphagia means difficulty swallowing.','Mechanical examples: esophageal tumor, stricture, diverticulum or extrinsic tumor compression.','Functional/neuromuscular examples: stroke, Parkinson disease, multiple sclerosis, myasthenia gravis, and achalasia.','Give any six supported distinct causes and explain mechanical narrowing versus impaired neuromuscular swallowing.'],refs('digestive',12,17))
writtenq('hyperhydration-types','Edema and body fluids','Define hyperhydration and give six examples divided into its three subtypes.',2,[23],['Hyperhydration is excess body fluid/water; its tonicity depends on relative sodium and water gain.','Isotonic: congestive heart failure; cirrhosis or nephrotic syndrome.','Hypotonic: SIADH; excessive compulsive water drinking.','Hypertonic: excess salt-water intake; aldosterone excess as the course table describes (hypernatremia may be absent because of compensatory water retention).','Do not copy the student response that classifies SIADH as isotonic. The supplied lecture classifies it as hypotonic.'],refs('hydration',28,40,52))
writtenq('hypokalemia-manifestations','Sodium and potassium','What are the clinical manifestations of hypokalemia in skeletal muscle, the heart, and the gastrointestinal tract?',3,[8,61],['Muscle weakness and reduced muscle function; severe depletion can impair respiratory muscles.','Cardiac electrical instability/tachyarrhythmias; flattened or inverted T waves, ST depression and prominent U waves.','Reduced smooth-muscle function with constipation, decreased motility and potentially paralytic ileus.','Do not use diarrhea as the expected direct effect of reduced intestinal motility; diarrhea is an important cause of potassium loss.'],refs('sodium-potassium',10,11,12,13))
writtenq('hydrostatic-examples','Edema and body fluids','Give four examples of edema caused by increased hydrostatic pressure.',3,[15,121],['Right-sided congestive heart failure.','Chronic venous insufficiency.','Deep venous thrombosis causing venous obstruction.','External venous compression by a tumor.'],refs('edema',6))
writtenq('ketoacidosis','Diabetic ketoacidosis','Describe the pathogenesis of ketoacidosis.',3,[119,140],['Insulin deficiency with counterregulatory hormone activity increases lipolysis and free-fatty-acid delivery to the liver.','Hepatic beta-oxidation generates acetyl-CoA; ketone-body production exceeds peripheral use.','Accumulation of ketoacids causes high-anion-gap metabolic acidosis.','In diabetes, hyperglycemia causes osmotic diuresis, fluid depletion and total-body electrolyte loss. Distinguish plasma potassium concentration from total-body potassium stores.'],refs('dka',2,3,4,5))

add('achalasia','Digestive system','The most typical disorder of lower esophageal sphincter relaxation caused by loss of esophageal nerve cells is called (choose one best answer)', ['Esophageal varices','Peptic ulcer','Gastroesophageal reflux disease','Achalasia',"Barrett’s esophagus"],[3],[34],'Loss of inhibitory neurons in the myenteric plexus impairs peristalsis and prevents appropriate relaxation of the lower esophageal sphincter. The lecture names this disorder achalasia.',refs('digestive',17))
add('edema-causes','Edema and body fluids','Causes of increased interstitial fluid volume and edema include', ['Reduced filtration pressure at the arterial end of the capillary','Increased capillary oncotic pressure','The action of histamine and related substances','Insufficient lymphatic circulation'],[2,3],[40],'Increased permeability in inflammation and impaired lymphatic drainage favor edema. Reduced capillary filtration pressure or increased plasma oncotic pressure would oppose the stated outward fluid movement.',refs('edema',4,5,13))
add('hypernatremia-sweating','Edema and body fluids','Select the important cause(s) of hypernatremia', ['Profuse sweating in patients with fever','A sterile forearm wound without signs of SIRS','SIADH','Fully compensated type 2 diabetes mellitus'],[0],[70,71],'Unreplaced hypotonic sweat loss removes relatively more water than sodium. SIADH causes water retention and dilutional hyponatremia; the other options do not describe a typical hypernatremic state.',refs('hydration',40,46,49))
add('not-high-gap-acidosis','Acid–base balance','Causes of normochloremic metabolic acidosis do NOT include', ['Starvation','Alcohol poisoning','Salicylate poisoning','Diabetes insipidus'],[3],[92],'The lecture lists starvation, alcoholic ketoacidosis and salicylates among high-anion-gap acidosis causes. Diabetes insipidus primarily causes hypotonic urinary water loss and hypernatremic dehydration; it is not itself one of these acid-accumulation mechanisms.',refs('acid-base',57)+refs('hydration',42,49))
add('hyperchloremic-mechanisms','Acid–base balance','Hyperchloremic acidosis', ['Is characterized by an increased anion gap','Is characterized by increased chloride and decreased bicarbonate','May result from impaired proximal tubular bicarbonate reabsorption','Cannot be caused by diarrheal disease'],[1,2],[104],'A fall in bicarbonate with relative chloride retention produces normal-anion-gap metabolic acidosis. Both intestinal bicarbonate loss and impaired proximal renal bicarbonate reabsorption can cause it.',refs('acid-base',54,61,62,65))
add('proximal-tubule-injury','Acid–base balance','Chronic lead poisoning damages the proximal renal tubules in a young patient. Assuming no other lead-related damage, select the likely findings.', ['Urinary bicarbonate is likely high','The patient likely has proximal tubular alkalosis','The patient likely has proximal tubular acidosis','The patient likely has both hyperkalemia and hypernatremia','The patient likely has hypokalemia'],[0,2,4],[127],'Failure of proximal bicarbonate reabsorption produces urinary bicarbonate loss and type II renal tubular acidosis. The course describes associated hyperchloremia and potassium loss. The three-option answer set also matches the readable Moodle feedback.',refs('acid-base',63,65,66))
add('mechanical-ileus-risk','Digestive system','Which pose a fatal risk in patients with mechanical ileus?', ['Weight loss','Absorption of bacterial toxins','A disorder of bile secretion','Hyperhydration','Dehydration'],[1,4],[32,138],'The obstruction lecture describes sequestration of fluid and vomiting causing hypovolemic shock, and bacterial overgrowth with ischemia, necrosis, perforation and sepsis. These are the acute lethal mechanisms represented by the toxin and dehydration options.',refs('digestive',51,54))
add('proximal-rta','Acid–base balance','Renal tubular acidosis of the proximal type', ['Causes hypochloremia due to impaired chloride reabsorption','Raises urinary pH, often into the alkaline range','Does not produce renal bicarbonate losses','Has a normal anion gap'],[1,3],[150],'Impaired proximal bicarbonate reabsorption causes bicarbonaturia, which can alkalinize urine while filtered bicarbonate exceeds the reduced reabsorptive threshold. Once plasma bicarbonate is depleted, urine can become acidic, so urine pH is not invariably high. The systemic disorder is a normal-anion-gap hyperchloremic acidosis.',refs('acid-base',28,61,65,66))
add('ketoacidosis-causes','Diabetic ketoacidosis','Ketoacidosis occurs in patients with', ['Simple starvation','Acute liver failure','Alcohol abuse','Uncontrolled type 1 diabetes','Tissue hypoxia'],[0,2,3],[7],'The acid–base lecture explicitly lists starvation, alcoholic ketoacidosis and type 1 diabetes. Tissue hypoxia primarily points to lactic acid accumulation, while the DKA lecture explains excess hepatic ketogenesis with insulin deficiency.',refs('acid-base',11,13,57)+refs('dka',2,3,4),paper=2)
add('ethylene-glycol','Acid–base balance','A 2-year-old boy may have drunk ethylene glycol. Metabolism produces toxic organic acids. Which acid–base change may develop if he is not treated?', ['Metabolic alkalosis','Respiratory acidosis','High-anion-gap metabolic acidosis','Low- or normal-anion-gap metabolic acidosis','Most probably no acid–base change'],[2],[14],'The lecture lists ethylene glycol among intoxications causing high-anion-gap metabolic acidosis. This is the source vignette’s delayed metabolic consequence, not a claim that the anion gap must already be high 20 minutes after ingestion.',refs('acid-base',53,54,57),paper=2)
add('hpylori','Digestive system','Choose the correct statement(s) about H. pylori', ['Treatment of H. pylori-associated disease includes antibiotics','It can cause duodenal peptic ulcer','It can cause gastric inflammation','It is the leading cause of chronic hepatitis B','Treatment of H. pylori-associated disease includes corticosteroids'],[0,1,2],[14],'The complete answer set is stated in Moodle feedback. The lectures directly support gastric inflammation and duodenal ulceration. Antibiotic treatment is retained from the source key; these passages are not a treatment regimen.',refs('digestive',35,38,42,44),basis='moodle-key',paper=2)
add('iron-deficiency','Anemia','Iron deficiency', ['Can be caused by menorrhagia','May cause fatigue, pallor and dizziness','Usually leads to macrocytic anemia','Usually leads to sideroblastic anemia','Can result from chronic low-grade gastrointestinal blood loss'],[0,1,4],[5],'The three-option answer set is reproduced from Moodle feedback. These lectures are not a comprehensive anemia course, so this question remains marked as source-key practice.',[],basis='moodle-key',paper=2)
add('pain-modulation','Pain','Choose the correct statement(s) about pain', ['Colicky pain is usually mild and chronic','Nociceptive pain arises from direct axonal injury in peripheral or central nerves','Pain is objective','Pain can be modulated by serotonin and noradrenaline systems','Pain can be caused by hypoxia'],[3,4],[6],'Moodle feedback identifies modulation by serotonin/noradrenaline systems and pain from hypoxia. The digestive lecture supports ischemia as a visceral-pain stimulus. The supplied lectures do not provide the full pain-neurobiology explanation, so the item retains source-key status.',refs('digestive',10),basis='moodle-key',paper=2)

# Supplement uncovered topics only with inspected, linked clinical references.
from external_bank import extend
extend(bank,add,refs,written)
# Do not promote source/lecture discrepancies into scored questions.
held=[q for q in bank if q['verification']=='pending']
bank=[q for q in bank if q['verification']!='pending']
for q in bank:
    if len(q['options'])<2 or not q['correct'] or any(i>=len(q['options']) for i in q['correct']):raise ValueError(q['id'])
    if q['verification']=='lecture-supported' and not q['evidence']:raise ValueError('Missing evidence '+q['id'])
for q in bank+written:
    for e in q['evidence']:
        assert e['excerpt'] in norm(lectures[e['lectureId']]['pages'][e['page']-1]['text'])

for paper,pages,title,reason in [
 (1,[12],'Hypokalemia and metabolic acidosis','The marked answer conflicts with the course: diarrhea and renal tubular acidosis can produce both hypokalemia and metabolic acidosis. This original option set is excluded from scoring.'),
 (1,[224],'Transfusion complications: “NOT” question','All recovered options can describe transfusion complications. No defensible unique answer is established from this wording.'),
 (1,[253],'Arthus and Raynaud phenomena','The combined stem treats Raynaud phenomenon as a universal hypersensitivity category. Its mechanism depends on the underlying condition; the wording needs clarification.'),
 (3,[99],'Acid–base case with inconsistent values','The supplied pH, carbon dioxide and base-excess values do not form a sufficiently consistent case. Chronicity also cannot be established from a single blood gas.'),
 (3,[111],'Cirrhosis and vomiting blood-gas case','The recovered measurements do not uniquely establish the mixed disorder indicated by the paper key. Kept as a source draft.'),
 (3,[97],'Dumping syndrome after surgery','More than one listed operation can cause dumping syndrome. The intended meaning of “most often” is not sufficiently specified.')]:
 held.append({'question':title,'explanation':reason,'sourceRefs':[{'paper':paper,'page':p} for p in pages],'evidence':[]})
notes=[{'title':'Lecture slide conflict: oxygen dissociation curve','detail':'The acid–base lecture contains conflicting shift wording. Decreased pH shifts the oxygen dissociation curve to the right. The linked respiratory-society reference supports the correction; the contradictory slide is not used as an answer key.','sourceRefs':[],'evidence':refs('acid-base',20,21),'externalReferences':[{'title':'European Respiratory Society · oxygen dissociation curve','url':'https://publications.ersnet.org/content/breathe/11/3/194'}]},
 {'title':'Japanese annotations describe different question variants','detail':'Printed questions and remembered modified exam versions are kept separate. Missing replacement options have not been invented.','sourceRefs':[{'paper':'image','page':1},{'paper':'image','page':2}],'evidence':[]},
 {'title':'Coverage and wording','detail':'This is a checked subset, not a complete conversion of all 446 pages. Readable duplicates are combined where appropriate. Minor spelling and layout errors are normalized; clipped or ambiguous choices stay in the source library. Source-key questions are distinguished from independently supported answers.','sourceRefs':[],'evidence':[]}]
payload={'questions':bank,'written':written,'held':held,'notes':notes,'lectureCount':len(lectures),'lecturePages':sum(len(d['pages']) for d in lectures.values())}
version=hashlib.sha256(json.dumps(payload,sort_keys=True).encode()).hexdigest()[:12]
(root/'papers/verified-bank.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf8')
(root/'papers/verified-bank.js').write_text('window.VERIFIED_CONTENT = '+json.dumps(payload,ensure_ascii=False)+';\nwindow.BANK_VERSION = '+json.dumps(version)+';',encoding='utf8')
print(json.dumps({'questions':len(bank),'lectureSupported':sum(q['verification']=='lecture-supported' for q in bank),'externalSupported':sum(q['verification']=='external-supported' for q in bank),'sourceKey':sum(q['verification'] in ('moodle-key','printed-key') for q in bank),'written':len(written),'held':len(held),'lecturePages':payload['lecturePages']}))
